api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.dm-sidebar {
width: 100%;
height: calc(100vh - 64px);
/* ✅ Fixed missing semicolons and removed margin-top that was breaking the layout */
background: #ffffff;
border-right: 1px solid #e5e7eb;
padding: 24px 16px;
display: flex;
flex-direction: column;
font-family: "Inter", sans-serif;
position: sticky;
top: 64px;
box-sizing: border-box;
margin-top:13%
}

/* ===============================
LOGO SECTION (Optional)
===============================*/

.dm-logo {
display: flex;
align-items: center;
margin-bottom: 30px;
cursor: pointer;
}

.dm-logo-icon {
width: 38px;
height: 38px;
background: #2563eb;
color: white;
border-radius: 10px;
display: flex;
align-items: center;
justify-content: center;
margin-right: 10px;
font-size: 16px;
}

.dm-title {
font-weight: 600;
font-size: 14px;
color: #111827;
}

.dm-sub {
font-size: 12px;
color: #6b7280;
}


/* ===============================
MENU
===============================*/

.dm-menu {
list-style: none;
padding: 0;
margin: 0;
flex: 1;
}

.dm-menu li {
margin-bottom: 6px;
}

.dm-menu a {
display: flex;
align-items: center;
padding: 10px 14px;
border-radius: 8px;
text-decoration: none;
font-size: 14px;
color: #374151;
transition: background 0.2s ease, color 0.2s ease;
}

.dm-menu a span {
font-weight: 500;
}

/* ✅ Added fixed width and text-align to icons so they stack perfectly */
.dm-menu a i {
width: 24px;
text-align: center;
margin-right: 12px;
color: #2563eb;
font-size: 15px;
transition: color 0.2s ease;
}


/* ===============================
HOVER
===============================*/

/* Refined hover to a soft gray instead of full blue for better UX */
.dm-menu li:not(.active) a:hover {
background: #f3f4f6;
color: #111827;
}

.dm-menu li:not(.active) a:hover i {
color: #1d4ed8;
}


/* ===============================
ACTIVE LINK
===============================*/

.dm-menu li.active a {
background: #2563eb;
color: #ffffff;
}

.dm-menu li.active a i {
color: #ffffff;
}


/* ===============================
FOOTER
===============================*/

.dm-footer {
font-size: 11px;
color: #9ca3af;
padding-top: 15px;
border-top: 1px solid #e5e7eb;
}

.dm-version {
margin-top: 3px;
}
